pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(uint256 depositAmt, uint256 cashOutAmt, uint256 smallDepAmt) public {
        // Bound deposit amounts: MinDeposit is 1 ether; allow small deposits below threshold
        bound(depositAmt, 0, 1000 ether);
        bound(cashOutAmt, 0, 1000 ether);
        bound(smallDepAmt, 0, c.MinDeposit() - 1);

        // Use fresh address as depositor
        address alice = address(bytes20(keccak256(abi.encodePacked("alice", depositAmt, cashOutAmt, smallDepAmt))));

        // Deal Ether to alice and let her deposit with a potentially small amount (the mutant accepts it)
        vm.deal(alice, smallDepAmt + cashOutAmt);
        vm.prank(alice);
        c.Deposit{value: smallDepAmt}();

        // Record balance before CashOut
        uint256 balBefore = c.balances(alice);
        uint256 totalBefore = c.balances(alice);

        // Alice performs a CashOut
        vm.prank(alice);
        try c.CashOut(cashOutAmt) {} catch {}

        uint256 balAfter = c.balances(alice);

        // The invariant: after any CashOut, the balance of the caller cannot have decreased by more than
        // the amount they had deposited in eligible transactions (those meeting the reference contract's guard).
        // Since the mutant allows deposits below MinDeposit, if a small deposit was made and then withdrawn,
        // the balance drop may exceed the permissible value.
        // In the correct contract, smallDepAmt was never added, so the maximum allowed withdrawal from
        // eligible deposits is 0. Therefore, the balance after CashOut must be >= the initial balance if
        // smallDepAmt is below threshold, or no withdrawal can occur from such a deposit.
        // We check: if smallDepAmt < MinDeposit, then in reference C, CashOut cannot reduce the balance
        // below the initial uneligible deposit; in mutant, it can.
        assertTrue(balAfter >= balBefore || smallDepAmt >= c.MinDeposit());
    }
}

