pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        address depositor = address(0x100);
        // Restrict to amounts that don't overflow and are non-zero
        vm.assume(depositAmount > 0 && depositAmount <= type(uint256).max - 0);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);
        // Give the depositor enough ether
        vm.deal(depositor, depositAmount);
        // Deposit via the public function
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();
        // Withdraw a subset of the deposit-equivalent balance
        vm.prank(depositor);
        c.CashOut(withdrawAmount);
        // Invariant: the balance of any depositor after a deposit and partial withdraw
        // should be at least the deposit amount minus the withdrawn amount.
        // However, the bug removes the MinDeposit guard, allowing tiny deposits that the reference
        // would reject. The reference invariant is: if a deposit was recorded, the deposited amount
        // was > MinDeposit. We encode this by checking that if depositAmount <= MinDeposit,
        // the deposit should have been ignored (balance should be 0 after deposit).
        // If depositAmount > MinDeposit, the deposit applies and the balance after withdrawal
        // should be exactly depositAmount - withdrawAmount.
        uint256 expectedBalance;
        if (depositAmount > c.MinDeposit()) {
            expectedBalance = depositAmount - withdrawAmount;
        } else {
            expectedBalance = 0;
        }
        assertEq(c.balances(depositor), expectedBalance);
    }
}

