pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address addr, uint256 deposit1, uint256 deposit2, uint256 cashAmt) public {
        vm.assume(addr != address(0) && addr != address(this));
        vm.assume(deposit1 > 1 ether && deposit2 > 1 ether);
        vm.assume(deposit1 + deposit2 >= cashAmt);

        vm.deal(addr, deposit1 + deposit2);

        vm.prank(addr);
        c.Deposit{value: deposit1}();

        vm.prank(addr);
        c.Deposit{value: deposit2}();

        uint balBefore = c.balances(addr);

        vm.prank(addr);
        try c.CashOut(cashAmt) {} catch {}

        uint balAfter = c.balances(addr);
        assertTrue(balAfter == balBefore - cashAmt);
    }
}

