import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 amt1, uint256 amt2, uint256 amt3) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        amt1 = bound(amt1, 0, 1000 ether);
        amt2 = bound(amt2, 0, 1000 ether);
        amt3 = bound(amt3, 0, 1000 ether);

        // actor deposits
        vm.deal(actor, amt1);
        vm.prank(actor);
        c.Deposit{value: amt1}();

        // we deposit
        vm.deal(address(this), amt2);
        c.Deposit{value: amt2}();

        // actor withdraws
        uint balBefore = c.balances(actor);
        if (amt3 > balBefore) amt3 = balBefore;
        vm.prank(actor);
        try c.CashOut(amt3) {} catch {}

        assertTrue(address(c).balance >= c.balances(actor) + c.balances(address(this)));
    }
}

