pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address depositor, uint256 depositAmount, uint256 cashOutAmount) public {
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(this));

        // Bound deposit to reasonable range including below and above MinDeposit
        depositAmount = bound(depositAmount, 0, 10 ether);

        // Precondition: depositor has no balance yet
        require(c.balances(depositor) == 0, "depositor already has balance");

        // Deposit from the depositor
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        // Determine expected balance based on reference logic: only deposits > MinDeposit count
        uint expectedBalance = depositAmount > c.MinDeposit() ? depositAmount : 0;

        // Bound cashOut to at most the actual balance (reference allows up to balance)
        cashOutAmount = bound(cashOutAmount, 0, c.balances(depositor));

        // Perform CashOut
        vm.prank(depositor);
        try c.CashOut(cashOutAmount) {} catch {}

        // After CashOut, the depositor's balance should be expectedBalance - cashOutAmount
        uint actualBalance = c.balances(depositor);
        assertTrue(actualBalance == expectedBalance - cashOutAmount);
    }
}

